pub fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut it = txt.chars();

    let last = match it.next_back() {
        Some(c) => c,
        None => return false, // empty string
    };

    if !last.is_ascii_alphabetic() {
        return false;
    }

    match it.next_back() {
        None => true,           // exactly one character and it's an ASCII letter
        Some(prev) => prev == ' ', // standalone: immediately preceded by a space
    }
}